// Supabase Edge Function: an MCP server for the model.
// handler.js is generated by `npm run build:api` from src/lib/mcp.
//
// Deploy it without JWT verification (it has its own keys, the same ones as the REST API):
//   supabase functions deploy mcp --no-verify-jwt
// It needs no secrets: SUPABASE_URL and SUPABASE_ANON_KEY are provided by the platform.
// The service_role key is not used.
import { createMcpHandler } from "./handler.js";

declare const Deno: { env: { toObject(): Record<string, string> }; serve(handler: (request: Request) => Promise<Response>): void };

Deno.serve(createMcpHandler(() => Deno.env.toObject()));
